function r5RunRecurring(int $id,?string $runDate=null):array{
    global $config;$s=r4ContextStore();requireAbility('recurring.manage',$s);$svc=new \Nexa\Recurring\RecurringJournalService();
    if($config['demo_mode']){
        $tpl=null;foreach($s['recurring_journal_templates']??[] as$r)if((int)$r['id']===$id)$tpl=$r;
        if(!$tpl||empty($tpl['active']))throw new RuntimeException('Template recurring tidak aktif.');
        enforceCompanyAccess($s,(int)$tpl['company_id']);$date=$runDate?:$tpl['next_run_date'];
        $entry=r4PostMultiLineJournal(['company_id'=>$tpl['company_id'],'branch_id'=>$tpl['branch_id'],'department_id'=>$tpl['department_id'],'date'=>$date,'description'=>$tpl['description'],'source'=>'recurring','document_type'=>'recurring','lines'=>$tpl['lines']],false);
        $s=loadStore();$rid=(int)($s['meta']['next_recurring_run_id']??1);$posted=empty($entry['approval_required']);$due=($posted&&!empty($tpl['auto_reverse']))?date('Y-m-d',strtotime($date.' +'.max(1,(int)($tpl['reverse_after_days']??1)).' days')):null;
        $s['recurring_journal_runs'][]=['id'=>$rid,'template_id'=>$id,'scheduled_date'=>$date,'journal_id'=>$entry['id']??null,'reversal_journal_id'=>null,'reversal_due_date'=>$due,'reversal_status'=>$due?'pending':'none','status'=>$posted?'posted':'approval'];
        foreach($s['recurring_journal_templates'] as&$r)if((int)$r['id']===$id)$r['next_run_date']=$svc->nextDate($date,$r['frequency']);unset($r);
        $s['meta']['next_recurring_run_id']=$rid+1;saveStore($s);return$entry+['reversal_due_date'=>$due];
    }
    $pdo=db();$pdo->beginTransaction();try{
