        $entry=r5InsertJournalInTransaction($pdo,$s,(int)$tpl['company_id'],$date,(string)$tpl['description'],$lines,'recurring',$tpl['branch_id']?(int)$tpl['branch_id']:null,$tpl['department_id']?(int)$tpl['department_id']:null);
        $due=!empty($tpl['auto_reverse'])?date('Y-m-d',strtotime($date.' +'.max(1,(int)($tpl['reverse_after_days']??1)).' days')):null;
        $pdo->prepare("INSERT INTO recurring_journal_runs(template_id,scheduled_date,journal_id,reversal_due_date,reversal_status,status) VALUES(?,?,?,?,?,'posted')")->execute([$id,$date,$entry['id'],$due,$due?'pending':'none']);
        $next=$svc->nextDate($date,(string)$tpl['frequency']);$pdo->prepare("UPDATE recurring_journal_templates SET next_run_date=?,last_run_at=NOW() WHERE id=?")->execute([$next,$id]);$pdo->commit();
    }catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
    return$entry+['next_run_date'=>$next,'reversal_due_date'=>$due];
}
